          align-items: center;
          gap: 0.2rem;
        }

        .insight-loading-dots {
          position: relative;
          width: 2em;
          display: inline-block;
        }

        .insight-loading-dots::after {
          content: '...';
          position: absolute;
          animation: insight-dots 1.5s infinite steps(4);
          overflow: hidden;
          white-space: nowrap;
        }

